#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to;
    int len;
};

static const double INF = 1e100;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n, m;
        if (!(cin >> n >> m)) return 0;
        if (n == 0 && m == 0) break;

        vector<vector<Edge>> g(n);
        for (int i = 0; i < m; ++i) {
            int a, b, d;
            cin >> a >> b >> d;
            --a; --b;
            g[a].push_back({b, d});
            g[b].push_back({a, d});
        }

        int s, t;
        cin >> s >> t;
        --s; --t;

        /*
          State: (city, speed)
          Speed is integer, nonnegative.
          At a city, if it's the start city we may choose initial speed 1 and leave.
          At every intermediate city with an acceleration device, speed can change by -1, 0, +1,
          but speed must stay >= 1 while traveling.
          To stop at the goal city, we must arrive there with speed 1
          (then decelerate to 0 at the goal).

          Since road lengths are integers and speed changes by 1, useful speeds are bounded.
          A safe bound is max road length, because traversing a road of length d requires speed <= d
          if we need positive time and standard interpretations of this classic problem.
          More generally, speed larger than maxLen is never beneficial in optimal paths here.
        */

        int maxLen = 0;
        for (int u = 0; u < n; ++u)
            for (auto &e : g[u])
                maxLen = max(maxLen, e.len);

        if (s == t) {
            cout << "0.000\n";
            continue;
        }

        int V = maxLen + 1; // speeds 0..maxLen
        vector<vector<double>> dist(n, vector<double>(V, INF));

        using State = tuple<double,int,int>; // dist, city, speed
        priority_queue<State, vector<State>, greater<State>> pq;

        // Start from city s at speed 0, and can accelerate to 1 before first road.
        dist[s][0] = 0.0;
        pq.push({0.0, s, 0});

        while (!pq.empty()) {
            auto [cd, u, v] = pq.top();
            pq.pop();
            if (cd != dist[u][v]) continue;

            // At city u, choose next speed nv differing by at most 1.
            for (int dv = -1; dv <= 1; ++dv) {
                int nv = v + dv;
                if (nv < 1 || nv > maxLen) continue; // need positive speed to traverse a road

                for (auto &e : g[u]) {
                    if (e.len % nv != 0) {
                        // Travel time is still valid as real number; no divisibility needed.
                    }
                    double nd = cd + (double)e.len / (double)nv;
                    if (nd + 1e-12 < dist[e.to][nv]) {
                        dist[e.to][nv] = nd;
                        pq.push({nd, e.to, nv});
                    }
                }
            }
        }

        // Need to be able to stop at goal: arrive with speed 1, then decelerate to 0 there.
        double ans = dist[t][1];
        if (ans >= INF / 2) {
            cout << "unreachable\n";
        } else {
            cout.setf(std::ios::fixed);
            cout << setprecision(3) << ans << "\n";
        }
    }

    return 0;
}

