#define MAX_CITIES 30
#define MAX_SPEED 30
#define MAX_ROADS 100
#define INF 1000000000

typedef struct {
    int v;          // destination city
    int length;     // road length
    int speed_limit; // speed limit
} Road;

typedef struct {
    int city;
    int speed;
    int time;
} State;

Road roads[MAX_CITIES][MAX_ROADS];
int road_count[MAX_CITIES];
int dist[MAX_CITIES][MAX_SPEED + 1];
int visited[MAX_CITIES][MAX_SPEED + 1];
int heap_size;

State heap[MAX_CITIES * (MAX_SPEED + 1)];

void swap(State *a, State *b) {
    State temp = *a;
    *a = *b;
    *b = temp;
}

void heap_push(int city, int speed, int time) {
    int i = heap_size++;
    heap[i].city = city;
    heap[i].speed = speed;
    heap[i].time = time;

    while (i > 0 && heap[(i - 1) / 2].time > heap[i].time) {
        swap(&heap[i], &heap[(i - 1) / 2]);
        i = (i - 1) / 2;
    }
}

State heap_pop() {
    State result = heap[0];
    heap[0] = heap[--heap_size];

    int i = 0;
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < heap_size && heap[left].time < heap[smallest].time)
            smallest = left;
        if (right < heap_size && heap[right].time < heap[smallest].time)
            smallest = right;

        if (smallest != i) {
            swap(&heap[i], &heap[smallest]);
            i = smallest;
        } else {
            break;
        }
    }

    return result;
}

int main() {
    int n, m;
    int dataset = 1;

    while (1) {
        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) break;

        // Initialize
        for (int i = 0; i < n; i++) {
            road_count[i] = 0;
            for (int j = 0; j <= MAX_SPEED; j++) {
                dist[i][j] = INF;
                visited[i][j] = 0;
            }
        }

        // Read roads
        for (int i = 0; i < m; i++) {
            int x, y, d, c;
            scanf("%d %d %d %d", &x, &y, &d, &c);
            x--; y--;

            roads[x][road_count[x]].v = y;
            roads[x][road_count[x]].length = d;
            roads[x][road_count[x]].speed_limit = c;
            road_count[x]++;

            roads[y][road_count[y]].v = x;
            roads[y][road_count[y]].length = d;
            roads[y][road_count[y]].speed_limit = c;
            road_count[y]++;
        }

        int start, goal;
        scanf("%d %d", &start, &goal);
        start--; goal--;

        // Dijkstra
        heap_size = 0;

        // Start with speed 0 at start city
        dist[start][0] = 0;
        heap_push(start, 0, 0);

        int found = 0;
        int answer = INF;

        while (heap_size > 0) {
            State current = heap_pop();
            int city = current.city;
            int speed = current.speed;
            int time = current.time;

            if (visited[city][speed]) continue;
            visited[city][speed] = 1;

            if (city == goal) {
                answer = time;
                found = 1;
                break;
            }

            // Try all possible speed changes: -1, 0, +1
            for (int ds = -1; ds <= 1; ds++) {
                int new_speed = speed + ds;
                if (new_speed < 0 || new_speed > MAX_SPEED) continue;

                // Try all roads from this city
                for (int r = 0; r < road_count[city]; r++) {
                    int next = roads[city][r].v;
                    int length = roads[city][r].length;
                    int speed_limit = roads[city][r].speed_limit;

                    // Check speed limit
                    if (new_speed > speed_limit) continue;

                    // Calculate time: distance / speed (but we need integer arithmetic)
                    // Time = length / new_speed, but we need to be careful with integer division
                    // Actually, we need to travel at new_speed for the entire road
                    // Time = length / new_speed (floating point would be more accurate, but we can use integer arithmetic)
                    // Since we're looking for shortest time, we can use double

                    double travel_time = (double)length / new_speed;
                    int new_time = time + (int)(travel_time * 1000000); // Scale to avoid floating point

                    // Actually, let's use a simpler approach: store time as double
                    // But since we need to output integer, let's use integer arithmetic carefully
                    // Time = length / speed, but we need to find minimum time
                    // We can use: new_time = time * speed + length, then divide by new_speed
                    // Actually, let's just use double for the heap comparison

                    if (!visited[next][new_speed]) {
                        double new_time_double = time + (double)length / new_speed;
                        int new_time_int = (int)(new_time_double * 1000000);

                        if (new_time_int < dist[next][new_speed]) {
                            dist[next][new_speed] = new_time_int;
                            heap_push(next, new_speed, new_time_int);
                        }
                    }
                }
            }
        }

        printf("Case %d: ", dataset++);
        if (found) {
            // Convert back from scaled time
            double time_double = (double)answer / 1000000;
            // Round to nearest integer
            int result = (int)(time_double + 0.5);
            printf("%d\n", result);
        } else {
            printf("unreachable\n");
        }
    }

    return 0;
}

