#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define INF 1e100
#define EPS 1e-12

typedef struct Edge {
    int to;
    int len;
    struct Edge *next;
} Edge;

typedef struct {
    double dist;
    int node;
    int speed;
} HeapNode;

typedef struct {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->sz = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, double dist, int node, int speed) {
    if (h->sz + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->sz;
    while (i > 1) {
        int p = i >> 1;
        if (h->a[p].dist <= dist) break;
        h->a[i] = h->a[p];
        i = p;
    }
    h->a[i].dist = dist;
    h->a[i].node = node;
    h->a[i].speed = speed;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1;
    while ((i << 1) <= h->sz) {
        int l = i << 1, r = l + 1, c = l;
        if (r <= h->sz && h->a[r].dist < h->a[l].dist) c = r;
        if (h->a[c].dist >= last.dist) break;
        h->a[i] = h->a[c];
        i = c;
    }
    if (h->sz >= 0) h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        Edge **adj = (Edge **)calloc(n, sizeof(Edge *));
        int maxLen = 0;

        for (int i = 0; i < m; i++) {
            int u, v, l;
            scanf("%d %d %d", &u, &v, &l);
            u--; v--;

            Edge *e1 = (Edge *)malloc(sizeof(Edge));
            e1->to = v; e1->len = l; e1->next = adj[u]; adj[u] = e1;

            Edge *e2 = (Edge *)malloc(sizeof(Edge));
            e2->to = u; e2->len = l; e2->next = adj[v]; adj[v] = e2;

            if (l > maxLen) maxLen = l;
        }

        int s, t;
        scanf("%d %d", &s, &t);
        s--; t--;

        /* Speed never needs to exceed maxLen:
           to traverse any road of length L, speed must satisfy speed <= L.
           Since L <= maxLen, larger speeds are useless. */
        int S = maxLen;

        double *dist = (double *)malloc(sizeof(double) * n * (S + 1));
        for (int i = 0; i < n * (S + 1); i++) dist[i] = INF;

        #define IDX(city, sp) ((city) * (S + 1) + (sp))

        MinHeap pq;
        heap_init(&pq, 1024);

        /* Start at city s with speed 0 */
        dist[IDX(s, 0)] = 0.0;
        heap_push(&pq, 0.0, s, 0);

        double ans = INF;

        while (!heap_empty(&pq)) {
            HeapNode cur = heap_pop(&pq);
            double cd = cur.dist;
            int u = cur.node;
            int sp = cur.speed;

            if (cd > dist[IDX(u, sp)] + EPS) continue;

            if (u == t && sp == 1) {
                ans = cd;
                break;
            }

            for (Edge *e = adj[u]; e; e = e->next) {
                int v = e->to;
                int L = e->len;

                for (int dsp = -1; dsp <= 1; dsp++) {
                    int nsp = sp + dsp;
                    if (nsp <= 0) continue;
                    if (nsp > L) continue; /* cannot exceed road limit */

                    double nd = cd + ((double)L / (double)nsp);
                    int id = IDX(v, nsp);
                    if (nd + EPS < dist[id]) {
                        dist[id] = nd;
                        heap_push(&pq, nd, v, nsp);
                    }
                }
            }
        }

        if (ans >= INF / 2) {
            printf("unreachable\n");
        } else {
            printf("%.10f\n", ans);
        }

        for (int i = 0; i < n; i++) {
            Edge *e = adj[i];
            while (e) {
                Edge *nxt = e->next;
                free(e);
                e = nxt;
            }
        }
        free(adj);
        free(dist);
        free(pq.a);
    }

    return 0;
}

