public class Main {
    static class Edge {
        int to, length, speedLimit;
        Edge(int to, int length, int speedLimit) {
            this.to = to;
            this.length = length;
            this.speedLimit = speedLimit;
        }
    }

    static class State implements Comparable<State> {
        int city, speed;
        double time;
        State(int city, int speed, double time) {
            this.city = city;
            this.speed = speed;
            this.time = time;
        }
        public int compareTo(State other) {
            return Double.compare(this.time, other.time);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int N = sc.nextInt();
            int M = sc.nextInt();
            if (N == 0 && M == 0) break;
            int S = sc.nextInt() - 1;
            int G = sc.nextInt() - 1;

            List<Edge>[] graph = new ArrayList[N];
            for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

            for (int i = 0; i < M; i++) {
                int x = sc.nextInt() - 1;
                int y = sc.nextInt() - 1;
                int d = sc.nextInt();
                int c = sc.nextInt();
                graph[x].add(new Edge(y, d, c));
                graph[y].add(new Edge(x, d, c));
            }

            double[][] dist = new double[N][31];
            for (int i = 0; i < N; i++) Arrays.fill(dist[i], Double.MAX_VALUE);
            PriorityQueue<State> pq = new PriorityQueue<>();
            dist[S][0] = 0;
            pq.offer(new State(S, 0, 0));

            while (!pq.isEmpty()) {
                State cur = pq.poll();
                if (cur.time > dist[cur.city][cur.speed]) continue;
                if (cur.city == G && cur.speed == 0) break;

                for (Edge e : graph[cur.city]) {
                    for (int dv = -1; dv <= 1; dv++) {
                        int ns = cur.speed + dv;
                        if (ns < 0 || ns > e.speedLimit) continue;
                        if (ns == 0 && dv != 0) continue;
                        double nt = cur.time + (double) e.length / ns;
                        if (nt < dist[e.to][ns]) {
                            dist[e.to][ns] = nt;
                            pq.offer(new State(e.to, ns, nt));
                        }
                    }
                }
            }

            double ans = Double.MAX_VALUE;
            for (int s = 0; s <= 30; s++) {
                ans = Math.min(ans, dist[G][s]);
            }

            if (ans == Double.MAX_VALUE) {
                System.out.println("unreachable");
            } else {
                System.out.printf("%.5f%n", ans);
            }
        }
    }
}

