public class Main {
    static final double INF = 1e18;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int N = sc.nextInt(); // cities
            if (N == 0) break;
            int M = sc.nextInt(); // roads
            int start = sc.nextInt();
            int goal = sc.nextInt();

            // roads: city1, city2, length, speed_limit, num_devices, device_positions
            // State: (city, speed), find min time
            int maxSpeed = 100;
            double[][] dist = new double[N + 1][maxSpeed + 1];
            for (double[] row : dist) Arrays.fill(row, INF);

            List<int[]>[] adj = new List[N + 1]; // adj[u] = list of road indices
            for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();

            int[][] roads = new int[M][];
            int[][] devPos = new int[M][];

            for (int i = 0; i < M; i++) {
                int u = sc.nextInt(), v = sc.nextInt(), len = sc.nextInt(), lim = sc.nextInt(), nd = sc.nextInt();
                roads[i] = new int[]{u, v, len, lim};
                devPos[i] = new int[nd];
                for (int j = 0; j < nd; j++) devPos[i][j] = sc.nextInt();
                Arrays.sort(devPos[i]);
                adj[u].add(new int[]{v, i});
                adj[v].add(new int[]{u, i});
            }

            PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
            dist[start][1] = 0;
            pq.offer(new double[]{0, start, 1});

            while (!pq.isEmpty()) {
                double[] cur = pq.poll();
                double d = cur[0]; int u = (int)cur[1], spd = (int)cur[2];
                if (d > dist[u][spd] + 1e-9) continue;
                for (int[] e : adj[u]) {
                    int v = e[0], ri = e[1];
                    int len = roads[ri][2], lim = roads[ri][3];
                    int[] dp2 = devPos[ri];
                    // DP over devices
                    int nd = dp2.length;
                    double[][] dp = new double[nd + 2][maxSpeed + 1];
                    for (double[] r : dp) Arrays.fill(r, INF);
                    dp[0][spd] = 0;
                    int[] pts = new int[nd + 2];
                    pts[0] = 0;
                    for (int j = 0; j < nd; j++) pts[j+1] = dp2[j];
                    pts[nd+1] = len;
                    for (int j = 0; j <= nd; j++) {
                        int segLen = pts[j+1] - pts[j];
                        for (int s = 1; s <= lim; s++) {
                            if (dp[j][s] == INF) continue;
                            // travel segment at speed s
                            double t = dp[j][s] + (double)segLen / s;
                            if (j < nd) {
                                // at device j+1, can change speed by -1,0,+1
                                for (int ds = -1; ds <= 1; ds++) {
                                    int ns = s + ds;
                                    if (ns >= 1 && ns <= lim && t < dp[j+1][ns]) { dp[j+1][ns] = t; }
                                }
                            } else {
                                if (t < dp[nd+1][s]) dp[nd+1][s] = t;
                            }
                        }
                    }
                    for (int ns = 1; ns <= lim; ns++) {
                        if (dp[nd+1][ns] < INF) {
                            double nd2 = d + dp[nd+1][ns];
                            if (nd2 < dist[v][ns]) { dist[v][ns] = nd2; pq.offer(new double[]{nd2, v, ns}); }
                        }
                    }
                }
            }
            double ans = INF;
            for (int s = 1; s <= maxSpeed; s++) ans = Math.min(ans, dist[goal][s]);
            if (ans == INF) System.out.println("unreachable");
            else System.out.printf("%.10f%n", ans);
        }
    }
}

